class Counter:
    instance_count = 0

    def __init__(self, name):
        self.name = name
        self.value = 0
        Counter.instance_count += 1

    def increment(self):
        self.value += 1
        return self.value

    @classmethod
    def reset_all(cls):
        cls.instance_count = 0

    @staticmethod
    def is_valid_name(name):
        return isinstance(name, str) and len(name) > 0
